 75→export function createRole(role: string): void {
 76→  const db = getDb();
 77→  const RESOURCES = [
 78→    "dashboard.summary", "dashboard.allocation", "dashboard.progress",
 79→    "candidates", "procedures", "actions",
 80→    "admin.data-sheet", "admin.workflow",
 81→    "system.permissions", "system.users",
 82→    "etc",
 83→  ];
 84→  const ACTIONS = ["view", "edit", "delete", "export", "import"];
 85→  const insert = db.prepare(
 86→    "INSERT OR IGNORE INTO permissions (role, resource, action, allowed) VALUES (?, ?, ?, 0)"
 87→  );
 88→  const tx = db.transaction(() => {
 89→    for (const resource of RESOURCES) {
 90→      for (const action of ACTIONS) {
 91→        insert.run(role, resource, action);
 92→      }
 93→    }
 94→  });
 95→  tx();
 96→}
 97→
 98→export function deleteRole(role: string): { success: boolean; error?: string } {
 99→  const db = getDb();
100→  const userCount = db
101→    .prepare("SELECT COUNT(*) as count FROM users WHERE role = ?")
102→    .get(role) as { count: number };
103→  if (userCount.count > 0) {
104→    return { success: false, error: `${userCount.count}명의 사용자가 이 역할을 사용 중입니다.` };
105→  }
106→  db.prepare("DELETE FROM permissions WHERE role = ?").run(role);
107→  return { success: true };
108→}
